/**
 * ROUND 188 -- a throwaway bucket index over points, for the build-time scans
 * that asked "anything within r of here?" by walking every building (or rock,
 * or doorstep) in the world. Five cities at three times the size put ~2,000
 * more buildings in that list, and three such scans went quadratic: measured,
 * the rock scatter's `blocked` 7.2s, the doorstep dedupe 2.1s and the wall's
 * rock test 2.4s of a 31s boot. `near` visits only the cells a disc of radius
 * r can touch, so it answers exactly what the full walk did.
 */
function bucketIndex(items, cell, getX = (o) => o.x, getY = (o) => o.y) {
  const map = new Map();
  const add = (o) => {
    const k = Math.floor(getX(o) / cell) + ',' + Math.floor(getY(o) / cell);
    let list = map.get(k);
    if (!list) { list = []; map.set(k, list); }
    list.push(o);
  };
  for (const o of items) add(o);
  return {
    add,
    /** Calls fn(o) for every item in a cell the disc (x, y, r) touches;
     *  stops and returns true as soon as fn does. */
    some(x, y, r, fn) {
      const c0 = Math.floor((x - r) / cell), c1 = Math.floor((x + r) / cell);
      const d0 = Math.floor((y - r) / cell), d1 = Math.floor((y + r) / cell);
      for (let cy = d0; cy <= d1; cy++) {
        for (let cx = c0; cx <= c1; cx++) {
          const list = map.get(cx + ',' + cy);
          if (list) for (const o of list) if (fn(o)) return true;
        }
      }
      return false;
    },
  };
}
