      // it rides on does not paint a second one (see `_specialStrike`).
      // Only when the cast DID paint one -- that is `requiresWeapon`.
      this._suppressSwingFx = !!a.requiresWeapon;
      try { this._doPlayerAttack('right'); } finally { this._strikeRider = null; this._suppressSwingFx = false; }
