        // that hits builds a mark too; a stacking effect that only counted
        // weapon swings would be dead weight in a caster build.
        if (isCrit) this._stackSpend('crit', t);
        this._stackEvent('hit', t);
        if (isCrit) this._stackEvent('crit', t);
        this._damageMonster(t, dmg, true, !el, el);
        this._applyAbilityDebuff(a, t);   // ROUND 57
        this._floatText(t.wx, t.wy - 30, isCrit ? `Crit! ${dmg}` : `${dmg}`, isCrit ? CRIT_COLOR : a.color);
