      // the identical code: if the player's taunt and Benjamin's taunt were two
      // implementations, one of them would be the one that got tuned.
      const n = this._applyTaunt(this._tauntSourcePlayer(), a);
      this._floatText(this.world.x, this.world.y - 40,
        n ? `${a.name} — ${n} on you` : `${a.name} — nothing heard it`, a.color);
